CREATE TABLE IF NOT EXISTS users (id uuid DEFAULT uuidv7() PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, zitadel_sub TEXT NOT NULL);
ALTER TABLE users ADD CONSTRAINT users_zitadel_sub_unique UNIQUE (zitadel_sub);
CREATE TABLE IF NOT EXISTS user_display_names (id BIGSERIAL PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, user_id uuid NOT NULL, display_name TEXT NOT NULL, CONSTRAINT fk_user_display_names_user_id__id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE INDEX user_display_names_user_id_id ON user_display_names (user_id, id);
CREATE TABLE IF NOT EXISTS households (id uuid DEFAULT uuidv7() PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS household_memberships (id BIGSERIAL PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, household_id uuid NOT NULL, user_id uuid NOT NULL, "role" TEXT NOT NULL, CONSTRAINT fk_household_memberships_household_id__id FOREIGN KEY (household_id) REFERENCES households(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_household_memberships_user_id__id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE INDEX household_memberships_household_id_id ON household_memberships (household_id, id);
CREATE INDEX household_memberships_user_id_id ON household_memberships (user_id, id);
CREATE TABLE IF NOT EXISTS household_membership_revocations (id BIGSERIAL PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, membership_id BIGINT NOT NULL, CONSTRAINT fk_household_membership_revocations_membership_id__id FOREIGN KEY (membership_id) REFERENCES household_memberships(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS catalog_items (id uuid DEFAULT uuidv7() PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, created_by uuid NOT NULL, CONSTRAINT fk_catalog_items_created_by__id FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS catalog_item_names (id BIGSERIAL PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, catalog_item_id uuid NOT NULL, "name" TEXT NOT NULL, edited_by uuid NOT NULL, CONSTRAINT fk_catalog_item_names_catalog_item_id__id FOREIGN KEY (catalog_item_id) REFERENCES catalog_items(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_catalog_item_names_edited_by__id FOREIGN KEY (edited_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE INDEX catalog_item_names_catalog_item_id_id ON catalog_item_names (catalog_item_id, id);
CREATE TABLE IF NOT EXISTS catalog_item_units (id BIGSERIAL PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, catalog_item_id uuid NOT NULL, unit TEXT NOT NULL, edited_by uuid NOT NULL, CONSTRAINT fk_catalog_item_units_catalog_item_id__id FOREIGN KEY (catalog_item_id) REFERENCES catalog_items(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_catalog_item_units_edited_by__id FOREIGN KEY (edited_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE INDEX catalog_item_units_catalog_item_id_id ON catalog_item_units (catalog_item_id, id);
CREATE TABLE IF NOT EXISTS products (id uuid DEFAULT uuidv7() PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, household_id uuid NOT NULL, catalog_item_id uuid NOT NULL, CONSTRAINT fk_products_household_id__id FOREIGN KEY (household_id) REFERENCES households(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_products_catalog_item_id__id FOREIGN KEY (catalog_item_id) REFERENCES catalog_items(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE products ADD CONSTRAINT uq_products_household_catalog UNIQUE (household_id, catalog_item_id);
CREATE TABLE IF NOT EXISTS product_minimum_stocks (id BIGSERIAL PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, product_id uuid NOT NULL, minimum_stock INT NOT NULL, edited_by uuid NOT NULL, CONSTRAINT fk_product_minimum_stocks_product_id__id FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_product_minimum_stocks_edited_by__id FOREIGN KEY (edited_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT check_product_minimum_stocks_0 CHECK (minimum_stock >= 0));
CREATE INDEX product_minimum_stocks_product_id_id ON product_minimum_stocks (product_id, id);
CREATE TABLE IF NOT EXISTS product_archives (id BIGSERIAL PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, product_id uuid NOT NULL, archived_by uuid NOT NULL, CONSTRAINT fk_product_archives_product_id__id FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_product_archives_archived_by__id FOREIGN KEY (archived_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE INDEX product_archives_product_id_id ON product_archives (product_id, id);
CREATE TABLE IF NOT EXISTS stock_replenishments (id BIGSERIAL PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, product_id uuid NOT NULL, quantity INT NOT NULL, occurred_at TIMESTAMP NOT NULL, acted_by uuid NOT NULL, note TEXT NULL, CONSTRAINT fk_stock_replenishments_product_id__id FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_stock_replenishments_acted_by__id FOREIGN KEY (acted_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT check_stock_replenishments_0 CHECK (quantity > 0));
CREATE INDEX stock_replenishments_product_id_id ON stock_replenishments (product_id, id);
CREATE TABLE IF NOT EXISTS stock_consumptions (id BIGSERIAL PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, product_id uuid NOT NULL, quantity INT NOT NULL, occurred_at TIMESTAMP NOT NULL, acted_by uuid NOT NULL, note TEXT NULL, CONSTRAINT fk_stock_consumptions_product_id__id FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_stock_consumptions_acted_by__id FOREIGN KEY (acted_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT check_stock_consumptions_0 CHECK (quantity > 0));
CREATE INDEX stock_consumptions_product_id_id ON stock_consumptions (product_id, id);
CREATE TABLE IF NOT EXISTS stock_event_corrections (id BIGSERIAL PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, target_table TEXT NOT NULL, target_id BIGINT NOT NULL, new_quantity INT NOT NULL, reason TEXT NULL, corrected_by uuid NOT NULL, CONSTRAINT fk_stock_event_corrections_corrected_by__id FOREIGN KEY (corrected_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT check_stock_event_corrections_0 CHECK ((target_table = 'stock_replenishments') OR (target_table = 'stock_consumptions')), CONSTRAINT check_stock_event_corrections_1 CHECK (new_quantity > 0));
CREATE INDEX stock_event_corrections_target_table_target_id_id ON stock_event_corrections (target_table, target_id, id);
